```python
from copy import deepcopy


def overlay_rows(base_rows, updates, mode):
    if not isinstance(base_rows, list) or not isinstance(updates, list):
        raise TypeError("row collections must be lists")
    if not isinstance(mode, str):
        raise TypeError("mode must be a string")
    if mode not in {"replace", "merge"}:
        raise ValueError("unsupported mode")

    def validate(rows):
        seen = set()
        for row in rows:
            if not isinstance(row, dict):
                raise TypeError("rows must be dictionaries")
            if "id" not in row:
                raise ValueError("row is missing id")
            if not isinstance(row["id"], str):
                raise TypeError("id must be a string")
            if row["id"] in seen:
                raise ValueError("duplicate id")
            seen.add(row["id"])

    validate(base_rows)
    validate(updates)
    pending = {row["id"]: row for row in updates}
    result = []
    for base in base_rows:
        update = pending.pop(base["id"], None)
        if update is None:
            result.append(deepcopy(base))
        elif mode == "replace":
            result.append(deepcopy(update))
        else:
            combined = deepcopy(update)
            combined.update(deepcopy(base))
            result.append(combined)
    for update in updates:
        if update["id"] in pending:
            result.append(deepcopy(update))
            del pending[update["id"]]
    return result
```

